function initTheme() {
  const savedTheme = localStorage.getItem('canyapi_theme') || 'dark';
  applyTheme(savedTheme);
  document.querySelectorAll('.js-theme-toggle').forEach(btn => {
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      const currentTheme = document.documentElement.getAttribute('data-theme') || 'dark';
      const newTheme = currentTheme === 'light' ? 'dark' : 'light';
      applyTheme(newTheme);
      localStorage.setItem('canyapi_theme', newTheme);
    });
  });
}
function applyTheme(theme) {
  document.documentElement.setAttribute('data-theme', theme);
  if (document.body) {
    document.body.classList.toggle('light-theme', theme === 'light');
  }
  const toggleBtns = document.querySelectorAll('.js-theme-toggle');
  toggleBtns.forEach(btn => {
    if (theme === 'light') {
      btn.innerHTML = '🌙 <span>Koyu</span>';
      btn.setAttribute('title', 'Koyu Temaya Geç');
    } else {
      btn.innerHTML = '☀️ <span>Açık</span>';
      btn.setAttribute('title', 'Açık Temaya Geç');
    }
  });
}
function initHeader() {
  const header = document.querySelector('.header');
  if (!header) return;
  window.addEventListener('scroll', function() {
    if (window.scrollY > 40) {
      header.classList.add('scrolled');
    } else {
      header.classList.remove('scrolled');
    }
  });
}
function initMobileNav() {
  const hamburgerBtns = document.querySelectorAll('.hamburger-btn, .mobile-toggle, .js-mobile-toggle');
  const closeBtns = document.querySelectorAll('.mobile-close-btn, .js-mobile-close');
  const overlay = document.querySelector('.mobile-nav-overlay');
  const drawer = document.querySelector('.mobile-nav-drawer');
  const servicesToggle = document.querySelector('.js-mobile-services-toggle');
  const submenu = document.querySelector('.mobile-submenu');
  function openMenu() {
    if (drawer && overlay) {
      drawer.classList.add('open');
      overlay.classList.add('open');
      document.body.style.overflow = 'hidden';
    }
  }
  function closeMenu() {
    if (drawer && overlay) {
      drawer.classList.remove('open');
      overlay.classList.remove('open');
      document.body.style.overflow = '';
    }
  }
  hamburgerBtns.forEach(btn => btn.addEventListener('click', function(e) {
    if (e && e.preventDefault) e.preventDefault();
    openMenu();
  }));
  closeBtns.forEach(btn => btn.addEventListener('click', function(e) {
    if (e && e.preventDefault) e.preventDefault();
    closeMenu();
  }));
  if (overlay) {
    overlay.addEventListener('click', function() {
      closeMenu();
    });
  }
  document.querySelectorAll('.mobile-nav-link:not(.js-mobile-services-toggle), .mobile-sub-link').forEach(link => {
    link.addEventListener('click', function() {
      closeMenu();
    });
  });
  if (servicesToggle && submenu) {
    servicesToggle.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      submenu.classList.toggle('open');
    });
  }
}
