function initQuoteModal() {
  const modalOverlay = ensureQuoteModalExists();
  const modalCloseBtn = modalOverlay.querySelector('#modalCloseBtn');
  const triggerBtns = document.querySelectorAll('.js-open-quote-modal');
  triggerBtns.forEach(btn => {
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      const service = this.getAttribute('data-service') || '';
      const isDiscovery = this.getAttribute('data-discovery') === 'true';
      openQuoteModal(service, isDiscovery);
    });
  });
  if (modalCloseBtn && modalOverlay) {
    modalCloseBtn.addEventListener('click', closeQuoteModal);
    modalOverlay.addEventListener('click', function(e) {
      if (e.target === modalOverlay) closeQuoteModal();
    });
  }
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') closeQuoteModal();
  });
  initFileUpload('modalFileInput', 'modalUploadBox', 'modalFilePreview');
}
window.openQuoteModal = function(serviceName = '', isDiscovery = false) {
  const modalOverlay = ensureQuoteModalExists();
  if (!modalOverlay) return;
  const serviceSelect = document.getElementById('modalServiceSelect');
  const discoveryCheckbox = document.getElementById('modalDiscoveryCheck');
  const modalTitle = document.getElementById('modalTitle');
  if (serviceSelect && serviceName) {
    serviceSelect.value = serviceName;
  }
  if (discoveryCheckbox) {
    discoveryCheckbox.checked = isDiscovery;
  }
  if (modalTitle) {
    modalTitle.innerText = isDiscovery ? 'Ücretsiz Keşif & Randevu Talebi' : 'Hemen Teklif Alın';
  }
  modalOverlay.classList.add('open');
  document.body.style.overflow = 'hidden';
  if (window.CanYapiAnalytics) {
    if (isDiscovery) {
      window.CanYapiAnalytics.track('free_discovery_click', { service: serviceName || 'Genel' });
    }
  }
};
window.closeQuoteModal = function() {
  const modalOverlay = document.getElementById('quoteModal');
  if (modalOverlay) {
    modalOverlay.classList.remove('open');
    document.body.style.overflow = '';
  }
};
function syncContactLinks() {
  document.querySelectorAll('a[href^="tel:"]').forEach(link => {
    link.href = `tel:${CAN_YAPI_CONFIG.phoneRaw}`;
  });
  document.querySelectorAll('.js-contact-phone').forEach(el => {
    el.textContent = CAN_YAPI_CONFIG.phone;
  });
  document.querySelectorAll('a[href*="wa.me"]').forEach(link => {
    try {
      const url = new URL(link.href);
      const query = url.search; // Varsa ?text=... kısmını koru
      link.href = `https://wa.me/${CAN_YAPI_CONFIG.whatsapp}${query}`;
    } catch (e) {
      const parts = link.href.split('?');
      const query = parts.length > 1 ? '?' + parts[1] : '';
      link.href = `https://wa.me/${CAN_YAPI_CONFIG.whatsapp}${query}`;
    }
  });
}
function getActiveSocialLinks() {
  try {
    const stored = localStorage.getItem('canyapi_social_links');
    if (stored) {
      const parsed = JSON.parse(stored);
      return { ...CAN_YAPI_CONFIG.social, ...parsed };
    }
  } catch (e) {
    console.warn('Sosyal medya verisi okuma hatası:', e);
  }
  return CAN_YAPI_CONFIG.social || {};
}
